// Cards for the panel genes without a hand-written card in conditions.ts, so the phone, the desk and the
// letters never show a bare gene symbol. Each row keeps the panel's condition name, inheritance, severity
// band and treatable_note (data/panel.json), with one plain line in English and Arabic. The lines stay
// general on purpose: a genetic counsellor explains the detail, and each card cites the GeneReviews search
// the panel cites for that gene. Client-safe: nothing here touches the server. tests/psi.test.ts checks
// that every panel gene has a card, with the panel's inheritance and severity.
import type { Condition, Text } from './conditions';

type T2 = [en: string, ar: string];
type Grade = Condition['severity'] | '';
/** [inheritance, severity band from the panel ('' = not graded there), name, what it does, care today, notes]. */
type Row = ['AR' | 'XL', Grade, T2, T2, T2, { carrierNote?: T2; maleNote?: T2 }?];

const SUPPORT: T2 = ['Supportive care: therapies and help for each symptom.', 'رعاية داعمة: علاجات تأهيلية ومساعدة لكل عرض.'];
