const PCD: T2 = ['The tiny hairs that clear mucus from the airways do not work well, causing a wet cough and chest, sinus and ear infections from early life; fertility can be affected.', 'لا تعمل جيداً الشعيرات الدقيقة التي تنظّف المخاط من المجاري التنفسية، فيحدث سعال رطب والتهابات في الصدر والجيوب والأذنين منذ الصغر، وقد تتأثر الخصوبة.'];
const PCD_CARE: T2 = ['Airway clearance and antibiotics.', 'تنظيف المجاري التنفسية والمضادات الحيوية.'];
const JOUBERT: T2 = ['Part of the brain that controls balance and coordination forms differently, causing weak muscle tone and delayed development, sometimes with eye or kidney problems.', 'يتكوّن جزء الدماغ المسؤول عن التوازن والتنسيق بشكل مختلف، فيحدث ارتخاء في العضلات وتأخر في النمو، وأحياناً مشكلات في العين أو الكلى.'];
const CILIA: T2 = ['Changes in this gene affect tiny structures on cells called cilia. Depending on the changes, a child can have Joubert syndrome (balance and development, sometimes eyes and kidneys) or Meckel syndrome, a severe condition affecting the brain and kidneys before birth.', 'تؤثر التغيّرات في هذا الجين في تراكيب دقيقة على الخلايا تُسمّى الأهداب. وبحسب التغيّرات قد يصاب الطفل بمتلازمة جوبير (التوازن والنمو، وأحياناً العينان والكليتان) أو بمتلازمة ميكل، وهي حالة شديدة تؤثر في الدماغ والكليتين قبل الولادة.'];
const ALBINISM: T2 = ['Light skin, hair and eyes from birth, with reduced vision and sensitivity to the sun.', 'بشرة وشعر وعينان فاتحة اللون منذ الولادة، مع ضعف في البصر وحساسية للشمس.'];
const SUN_EYES: T2 = ['Sun protection and vision care.', 'الحماية من الشمس ورعاية البصر.'];
