const BBS: T2 = ['Affects many parts of the body: vision loss from childhood, weight gain, extra fingers or toes, kidney problems and learning difficulties.', 'تؤثر في أجزاء كثيرة من الجسم: ضعف البصر منذ الطفولة، وزيادة الوزن، وأصابع زائدة في اليدين أو القدمين، ومشكلات في الكلى، وصعوبات في التعلم.'];
const BBS_CARE: T2 = ['Care for each symptom; setmelanotide for weight.', 'رعاية لكل عرض، ودواء السيتميلانوتايد للوزن.'];
const HAEMOPHILIA_CARRIER: T2 = ['Most women who carry it clot normally, but some bleed more than usual, so a doctor can check their clotting-factor level, for example before surgery or childbirth.', 'تتجلط دماء معظم النساء الحاملات بشكل طبيعي، لكن بعضهن ينزفن أكثر من المعتاد، لذا يستطيع الطبيب فحص مستوى عامل التجلط، مثلاً قبل الجراحة أو الولادة.'];
const HAEMOPHILIA_MAN: T2 = ['For a man with this result: mild haemophilia can go unnoticed until bleeding lasts too long after surgery, a tooth extraction or an injury, so a doctor should check your clotting-factor level. Before any surgery or dental work, tell the team: you may need treatment first.', 'للرجل الذي لديه هذه النتيجة: قد يمرّ الناعور الخفيف دون أن يُلاحظ حتى يطول النزف بعد جراحة أو خلع سن أو إصابة، لذا ينبغي أن يفحص الطبيب مستوى عامل التجلط لديك. وقبل أي جراحة أو علاج للأسنان أخبر الفريق المعالج، فقد تحتاج إلى علاج قبلها.'];
/** For conditions that show early in boys: a healthy man with the finding is unexpected. */
const recheck = (en = '', ar = ''): T2 => [
  `In a healthy man this result should be re-checked by the lab before anything else. The condition usually shows early in boys, so in a man without symptoms the result may need correcting, or the change may be in only some of his cells. ${en}${en && ' '}A genetic counsellor can explain.`,
  `لدى الرجل السليم ينبغي أن يعيد المختبر فحص هذه النتيجة قبل أي خطوة أخرى. فالحالة تظهر عادة مبكراً لدى الأولاد، لذا قد تحتاج النتيجة لدى رجل بلا أعراض إلى تصحيح، أو قد يكون التغيّر موجوداً في بعض خلاياه فقط. ${ar}${ar && ' '}ويستطيع المرشد الوراثي أن يشرح ذلك.`,
];
const RECHECK = recheck();

