  EYS: ['AR', '', ['Retinitis pigmentosa (EYS)', 'التنكس الشبكي الصباغي (EYS)'], RP, NO_THERAPY],
  RPGRIP1: ['AR', '', ['Leber congenital amaurosis / cone-rod dystrophy (RPGRIP1)', 'داء ليبر الخلقي / ضمور المخاريط والعصي (RPGRIP1)'], ['Severe vision loss from birth or early childhood, or a later loss of sharp and colour vision.', 'ضعف شديد في البصر منذ الولادة أو الطفولة المبكرة، أو ضعف لاحق في حدة البصر وإدراك الألوان.'], NO_THERAPY],
  CDH23: ['AR', '', ['Usher syndrome type 1D / DFNB12 hearing loss', 'متلازمة أشر من النوع 1D / فقدان السمع DFNB12'], ['Ranges from Usher syndrome (deafness from birth, balance problems and vision that fades from childhood) to hearing loss alone.', 'يتراوح من متلازمة أشر (صمم منذ الولادة، ومشكلات في التوازن، وبصر يضعف منذ الطفولة) إلى فقدان السمع وحده.'], USHER_CARE],
  ABCC6: ['AR', '', ['Pseudoxanthoma elasticum / generalized arterial calcification of infancy', 'الورم الأصفر المرن الكاذب / التكلس الشرياني المعمم في الرضاعة'], ['Calcium builds up in elastic tissues. In infancy it can harden the arteries severely; later in life it affects the skin, eyes and blood vessels.', 'يتراكم الكالسيوم في الأنسجة المرنة. وفي الرضاعة قد يصلّب الشرايين بشدة، وفي مراحل لاحقة من العمر يؤثر في الجلد والعينين والأوعية الدموية.'], SUPPORT],
  MPL: ['AR', '', ['Congenital amegakaryocytic thrombocytopenia', 'قلة الصفيحات الخلقية مع غياب النواءات'], ['The bone marrow makes too few platelets from birth, causing bleeding, and later it can stop making other blood cells too.', 'يصنع نخاع العظم صفائح دموية قليلة جداً منذ الولادة، فيحدث نزف، وقد يتوقف لاحقاً عن صنع خلايا الدم الأخرى أيضاً.'], ['A stem-cell transplant.', 'زراعة الخلايا الجذعية.']],
  NCF1: ['AR', '', ['Chronic granulomatous disease (p47phox)', 'داء الورم الحبيبي المزمن (p47phox)'], ['White blood cells cannot kill some bacteria and fungi, causing serious, repeated infections.', 'لا تستطيع كريات الدم البيضاء قتل بعض البكتيريا والفطريات، فتحدث عدوى خطيرة متكررة.'], ['Medicines to prevent infection; a stem-cell transplant.', 'أدوية للوقاية من العدوى، وزراعة الخلايا الجذعية.']],
