  TMEM67: ['AR', '', ['Meckel / Joubert / COACH syndrome (TMEM67)', 'متلازمة ميكل / جوبير / COACH (TMEM67)'], ['Affects tiny structures on cells called cilia. It ranges from the severe Meckel syndrome before birth to Joubert syndrome, or COACH syndrome, which also affects the liver.', 'يؤثر في تراكيب دقيقة على الخلايا تُسمّى الأهداب، ويتراوح من متلازمة ميكل الشديدة قبل الولادة إلى متلازمة جوبير، أو متلازمة COACH التي تؤثر أيضاً في الكبد.'], SUPPORT],
  INPP5E: ['AR', '', ['Joubert syndrome 1', 'متلازمة جوبير من النوع الأول'], JOUBERT, SUPPORT],
  LIFR: ['AR', '', ['Stuve-Wiedemann syndrome', 'متلازمة ستوف-فيدمان'], ['Bowed bones and stiff joints, with episodes of trouble breathing and feeding and high temperature in infancy, which need close care.', 'عظام مقوّسة ومفاصل متيبسة، مع نوبات من صعوبة التنفس والرضاعة وارتفاع الحرارة في الرضاعة تحتاج إلى رعاية دقيقة.'], SUPPORT],
  GLB1: ['AR', 'profound', ['GM1 gangliosidosis / Morquio B', 'داء اختزان الغانغليوزيد GM1 / داء موركيو من النوع B'], ['A fatty substance builds up in the brain and body. The infant form is severe and later forms are milder; Morquio B mainly affects the bones.', 'تتراكم مادة دهنية في الدماغ والجسم. وشكل الرضاعة شديد، والأشكال المتأخرة أخف، أما داء موركيو B فيؤثر أساساً في العظام.'], SUPPORT],
  MAN2B1: ['AR', 'severe', ['Alpha-mannosidosis', 'داء المانوزيدات ألفا'], ['Sugars build up in cells, causing hearing loss, learning difficulties, frequent infections and changes in the bones from childhood.', 'تتراكم السكريات في الخلايا، فيحدث فقدان في السمع وصعوبات في التعلم وعدوى متكررة وتغيّرات في العظام منذ الطفولة.'], ['Enzyme replacement (velmanase alfa) and stem-cell transplant.', 'العلاج بتعويض الإنزيم (فيلماناز ألفا) وزراعة الخلايا الجذعية.']],
  ETFDH: ['AR', '', ['Multiple acyl-CoA dehydrogenase deficiency (glutaric aciduria type 2)', 'نقص نازعات هيدروجين الأسيل المتعدد (بيلة الحمض الغلوتاري من النوع الثاني)'], ['The body cannot use fats and some proteins for energy. Severe forms show in newborns; milder forms cause muscle weakness, or episodes during illness or fasting, later in life.', 'لا يستطيع الجسم استخدام الدهون وبعض البروتينات للطاقة. وتظهر الأشكال الشديدة لدى حديثي الولادة، أما الأشكال الأخف فتسبب لاحقاً ضعفاً في العضلات أو نوبات أثناء المرض أو الصيام.'], ['Riboflavin (vitamin B2) for responsive forms, avoiding fasting, and diet.', 'الريبوفلافين (فيتامين B2) للأشكال المستجيبة، وتجنّب الصيام، ونظام غذائي مناسب.']],
  GCDH: ['AR', 'moderate', ['Glutaric aciduria type 1', 'بيلة الحمض الغلوتاري من النوع الأول'], ['Without treatment, an illness in infancy or early childhood can bring lasting damage to the part of the brain that controls movement.', 'من دون علاج قد يسبب مرض في الرضاعة أو الطفولة المبكرة ضرراً دائماً في جزء الدماغ الذي يتحكم في الحركة.'], ['Treatable: a lysine-restricted diet, carnitine and an emergency plan for illness; found by newborn screening.', 'قابل للعلاج: نظام غذائي يحدّ من الليسين، والكارنيتين، وخطة طوارئ عند المرض، ويكشفه فحص حديثي الولادة.']],
  SLC26A3: ['AR', '', ['Congenital chloride diarrhea', 'الإسهال الكلوري الخلقي'], ['Watery diarrhoea from before birth, with loss of salt and water from the body.', 'إسهال مائي منذ ما قبل الولادة، مع فقدان الأملاح والماء من الجسم.'], ['Lifelong salt replacement.', 'تعويض الأملاح مدى الحياة.']],
  CYP11B1: ['AR', 'moderate', ['Congenital adrenal hyperplasia (11-beta-hydroxylase deficiency)', 'تضخم الغدة الكظرية الخلقي (نقص إنزيم 11-بيتا هيدروكسيلاز)'], ['The adrenal glands cannot make enough cortisol. Girls may be born with genitals that look different, and children of either sex can grow fast and enter puberty early, sometimes with high blood pressure.', 'لا تصنع الغدتان الكظريتان ما يكفي من الكورتيزول. وقد تولد البنات بأعضاء تناسلية يختلف مظهرها، وقد ينمو الأطفال من الجنسين بسرعة ويبلغون مبكراً، أحياناً مع ارتفاع ضغط الدم.'], ['Treatable: glucocorticoid replacement.', 'قابل للعلاج: تعويض الغلوكوكورتيكويد.']],
  QDPR: ['AR', '', ['Dihydropteridine reductase deficiency (BH4 deficiency)', 'نقص إنزيم ثنائي هيدروبتيريدين ريدكتاز (نقص BH4)'], ['The brain cannot make some of its chemical messengers, causing seizures, movement problems and delayed development from infancy.', 'لا يستطيع الدماغ صنع بعض نواقله الكيميائية، فتحدث نوبات صرع ومشكلات في الحركة وتأخر في النمو منذ الرضاعة.'], ['L-dopa, 5-hydroxytryptophan, folinic acid and diet.', 'الليفودوبا، و5-هيدروكسي تريبتوفان، وحمض الفولينيك، ونظام غذائي مناسب.']],
  MYO7A: ['AR', 'moderate', ['Usher syndrome type 1B', 'متلازمة أشر من النوع 1B'], USHER1, USHER_CARE],
  RPE65: ['AR', '', ['Leber congenital amaurosis 2 (RPE65 retinopathy)', 'داء ليبر الخلقي من النوع الثاني (اعتلال الشبكية المرتبط بجين RPE65)'], ['Severe vision loss from early childhood, especially in dim light.', 'ضعف شديد في البصر منذ الطفولة المبكرة، خصوصاً في الضوء الخافت.'], ['Gene therapy (voretigene neparvovec).', 'علاج جيني (فوريتيجين نيبارفوفيك).']],
  DOCK8: ['AR', '', ['DOCK8 deficiency (combined immunodeficiency, hyper-IgE)', 'نقص DOCK8 (عوز مناعي مشترك مع فرط الغلوبولين المناعي E)'], ['The immune system is weak, causing severe eczema, allergies and repeated skin, chest and viral infections.', 'يكون الجهاز المناعي ضعيفاً، فتحدث إكزيما شديدة وحساسية وعدوى متكررة في الجلد والصدر وعدوى فيروسية.'], ['A stem-cell transplant.', 'زراعة الخلايا الجذعية.']],
  RAG1: ['AR', '', ['Severe combined immunodeficiency / Omenn syndrome (RAG1)', 'العوز المناعي المشترك الشديد / متلازمة أومن (RAG1)'], ['Babies are born without working immune cells, so infections are severe; it needs treatment in the first months of life.', 'يولد الأطفال دون خلايا مناعية عاملة، فتكون العدوى شديدة، ويحتاج ذلك إلى علاج في الأشهر الأولى من العمر.'], ['A stem-cell transplant; newborn screening (TREC) can find it.', 'زراعة الخلايا الجذعية، ويمكن أن يكشفه فحص حديثي الولادة (TREC).']],
